import java.util.Scanner;

class BankAccount {
    double balance;

    BankAccount(double balance) {
        this.balance = balance;
    }

    void displayBalance() {
        System.out.printf("Parent Balance: %.2f\n", balance);
    }
}

class SavingsAccount extends BankAccount {
    double balance;
    double rate;

    SavingsAccount(double bankBalance, double savingsBalance, double rate) {
        super(bankBalance);
        this.balance = savingsBalance;
        this.rate = rate;
    }

    @Override
    void displayBalance() {
        super.displayBalance();
        double interest = this.balance * this.rate / 100;
        double finalBalance = this.balance + interest;
        System.out.printf("Savings Balance: %.2f\n", finalBalance);
    }
}

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        double bankBalance = scanner.nextDouble();
        double savingsBalance = scanner.nextDouble();
        double rate = scanner.nextDouble();

        SavingsAccount account = new SavingsAccount(bankBalance, savingsBalance, rate);
        account.displayBalance();
    }
}

